import{z as r,x as c,o as i,c as P,q as n,j as t,D as e,d as B,s,S as E}from"./chunks/framework.C8m1ZpeB.js";const d=JSON.parse('{"title":"NVLink / NVSwitch","description":"","frontmatter":{"title":"NVLink / NVSwitch","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/nvlink.md","filePath":"llm/nvlink.md","lastUpdated":1791413859000}'),o={name:"llm/nvlink.md"};function A(C,a,N,h,V,p){const l=c("Mermaid");return i(),P("div",null,[a[2]||(a[2]=n('<h1 id="nvlink-nvswitch" tabindex="-1">NVLink / NVSwitch <a class="header-anchor" href="#nvlink-nvswitch" aria-label="Permalink to &quot;NVLink / NVSwitch&quot;">​</a></h1><div class="epigraph"><p>NVLink 是 GPU 之间的专用互连；NVSwitch 把多条 NVLink 收成一个平坦域。没有交换，链路只是点对点；没有链路，交换无物可转。</p><footer>—— NVIDIA NVLink / NVLink Switch 产品说明与各代 GPU 数据手册中的已公布带宽</footer></div><p><a href="/llm/mps-mig">上一课</a>把一张卡上的并发写成两条：MPS 提高占用、隔离弱；MIG 硬件切片、适合多租户。缺口是卡与卡之间：PCIe 按 I/O 总线设计，喂不动最密的集合通信。本课写 NVLink 链路与 NVSwitch 域，以及软件怎样踩中它们。不重讲 MIG 路数，也不编造未公开的单 lane 波特率。系统形态见 <a href="/llm/gb200-nvl72">NVL72</a>；拓扑对比见 <a href="/llm/all-to-all-vs-clos">全互连 vs Clos</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>只有 NVLink、没有 Switch 时，拓扑往往是 GPU 之间的有限全连接或环：8 卡 HGX 靠底板把每张卡的链路接到其他卡或接到板上的 Switch。链路数不够时，最远一对要转发，All-Reduce 的最慢边拖住一步。NVSwitch 把「转发」收进交换芯片，软件看见的是对称域。问题变成：域有多大、每 GPU 注入带宽多少、域与 PCIe / 网卡如何并存。</p><p><span class="marginnote">直觉类比：没有交换的多卡像一排只能和邻座通电话的人——传话给远处要一张嘴接一张嘴，最远那对费时最长；NVSwitch 像给全屋装了对讲总机，谁呼谁都一步接通，软件也省掉了「谁挨着谁」的记路负担。</span></p><p>公开对照（NVIDIA 手册 / 产品页）：A100 第三代 NVLink 600 GB/s；H100 SXM 900 GB/s，H100 NVL 形态写 600 GB/s，不可混列；Blackwell 第五代 1.8 TB/s。PCIe Gen5 在 H100 产品页为 128 GB/s。NVLink-C2C 把 Grace 与 GPU 相连，技术博客写双向 900 GB/s，那是 CPU–GPU，不是 GPU–GPU 的第五代 1.8 TB/s。三组数字出现在同一 Superchip 上，规划时必须分开。</p><h3 id="点对点、板上交换、柜级交换" tabindex="-1">点对点、板上交换、柜级交换 <a class="header-anchor" href="#点对点、板上交换、柜级交换" aria-label="Permalink to &quot;点对点、板上交换、柜级交换&quot;">​</a></h3><p>点对点：两张卡直连若干条 NVLink，适合 2 卡桥接。板上 / 节点内 Switch：HGX 8 卡，NVSwitch 让 8 张卡全互连，每卡仍按该代的 600 / 900 / 1800 GB/s 注入。柜级 Switch：NVL72 的 9 个交换托盘，72 张卡一个域，注入仍是每 GPU 1.8 TB/s，聚合写成 130 TB/s。三代都是「链路 + 交换」，变的是链路代数与域的半径。没有柜级 Switch 时，不要假设 16 张卡仍是 NVLink 平坦域——跨节点通常是 InfiniBand，除非某代 DGX 明确提供多节点 NVLink 域，且以那份产品说明为准。</p><p><span class="marginnote">600、900、1800 GB/s 是每 GPU 的双向聚合规格，不是「每条物理 lane 的用户可用吞吐」。把它们除以链路条数去还原单条速率，若手册没写，就不要写进容量规划。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>软件侧只做一件事：让最密的通信走 NVLink 域，而不是 PCIe 或网卡。NCCL 会查询拓扑；用户要保证进程绑定、<code>CUDA_VISIBLE_DEVICES</code>、以及并行网格与域一致。P2P 必须使能，否则拷贝绕道主机。<code>nvidia-smi topo -m</code> 上看 NVLink 连接；若两张本应在域内的卡之间显示走 PHB / PIX，先修 PCIe / 绑定，再谈算法。</p><p><span class="marginnote">术语翻译：P2P（点对点）指两张 GPU 不经过主机内存、直接互访对方显存的能力；关掉它，所有卡间拷贝都绕道主机。busbw 是 nccl-tests 报出的「总线带宽」，拿它和该代 NVLink 规格对表——差距大就说明路径不对。</span></p>',13)),(i(),t(E,null,{default:e(()=>[s(l,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20LR%0A%20%20GPU1%5B%22GPU%22%5D%20--%3E%7C%22NVLink%22%7C%20SW%5B%22NVSwitch%22%5D%0A%20%20GPU2%5B%22GPU%22%5D%20--%3E%7C%22NVLink%22%7C%20SW%0A%20%20GPU3%5B%22GPU%22%5D%20--%3E%7C%22NVLink%22%7C%20SW%0A%20%20SW%20--%3E%20DOM%5B%22%E5%B9%B3%E5%9D%A6%20GPU%20%E5%9F%9F%22%5D%0A%20%20GPU1%20--%3E%7C%22PCIe%22%7C%20CPU%5B%22%E4%B8%BB%E6%9C%BA%22%5D%0A%20%20GPU1%20--%3E%7C%22%E7%BD%91%E5%8D%A1%22%7C%20NIC%5B%22IB%20%2F%20%E4%BB%A5%E5%A4%AA%E7%BD%91%22%5D%0A%20%20DOM%20--%3E%20TP%5B%22TP%20%2F%20%E5%9F%9F%E5%86%85%20EP%22%5D%0A%20%20NIC%20--%3E%20DP%5B%22DP%20%2F%20%E8%B7%A8%E6%9F%9C%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[B(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=n('<p>集合通信在域内应显示 NVLink 传输，<code>nccl-tests</code> 的 busbw 应接近该代规格的一个合理分数，而不是接近网卡。达不到时，先查是否混进了跨域 rank、是否关掉了 P2P、是否在 MIG 切片之间强行 P2P。超节点上，18 个计算托盘的 GPU 都要经交换托盘互达；把 NCCL 绑到 Socket 等于绕开 Switch。同一条 All-Reduce 在 NVLink 上是加速器互连档的延迟，落到网卡就变成数据中心 hop；调 TP 度之前用微基准确认路径，比先改模型并行网格更便宜。</p><h3 id="与-c2c、pcie-的分工" tabindex="-1">与 C2C、PCIe 的分工 <a class="header-anchor" href="#与-c2c、pcie-的分工" aria-label="Permalink to &quot;与 C2C、PCIe 的分工&quot;">​</a></h3><p>NVLink GPU–GPU：模型并行、域内 KV。NVLink-C2C：Grace 与 GPU 之间的主机侧批量、统一内存叙事，900 GB/s 双向是官方数。PCIe：插卡、与不在 NVLink 域里的设备、部分网卡。H100 的 128 GB/s PCIe Gen5 相对 900 GB/s NVLink 差一档，所以「经主机转发的 GPU 拷贝」会把 TP 打死。不要用 C2C 的 900 GB/s 去满足 72 卡 All-to-All——那条路不经过 NVSwitch 的 GPU 交叉。</p><p>柜外仍是网卡。第五代 NVLink 再快，也不替代 ConnectX 的 Scale-Out。GB300 产品页写每 GPU 800 Gb/s 的 SuperNIC，与 1.8 TB/s 的 NVLink 同时存在：一个出柜，一个留柜。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>NVLink 是专用 SerDes 与协议，面向 GPU 内存语义的短消息与块传输，走 NVSwitch 时在交换芯片内部交叉。协议细节以 NVIDIA 公开白皮书为准，本文不复述未公开的 flit 格式。对软件，机制体现为：<code>cudaMemcpyPeer</code> 与 NCCL 的 NVLink 路径不经过主机 DRAM；延迟按加速器互连计。NVSwitch 提供多端口交叉，使域的直径不随「邻居转发」变长。SHARP 一类网内归约若在某代 NVSwitch 上提供，那是交换侧的计算，不是 GPU Tensor Core；是否启用看该代文档，不要假设每一代 Switch 都有同样的网内归约。</p>',6)),(i(),t(E,null,{default:e(()=>[s(l,{id:"mermaid-56",class:"mermaid",graph:"flowchart%20TD%0A%20%20CP%5B%22%E4%B8%80%E6%AC%A1%20GPU%20%E5%88%B0%20GPU%20%E7%9A%84%20P2P%20%E6%8B%B7%E8%B4%9D%22%5D%20--%3E%20Q%7B%22P2P%20%E4%BD%BF%E8%83%BD%E4%BA%86%E5%90%97%EF%BC%9F%22%7D%0A%20%20Q%20--%20%22%E5%90%A6%22%20--%3E%20HOST%5B%22%E7%BB%8F%E4%B8%BB%E6%9C%BA%20DRAM%20%E4%B8%AD%E8%BD%AC%EF%BC%9APCIe%20%E4%B8%A4%E8%B7%B3%22%5D%0A%20%20HOST%20--%3E%20SLOW%5B%22TP%20%E9%80%9F%E5%BA%A6%E8%A2%AB%E6%89%93%E6%AD%BB%22%5D%0A%20%20Q%20--%20%22%E6%98%AF%22%20--%3E%20SW%7B%22%E5%9F%9F%E5%86%85%E6%9C%89%20NVSwitch%EF%BC%9F%22%7D%0A%20%20SW%20--%20%22%E6%9C%89%22%20--%3E%20XF%5B%22%E4%BA%A4%E6%8D%A2%E8%8A%AF%E7%89%87%E5%86%85%E4%BA%A4%E5%8F%89%EF%BC%8C%E5%B9%B3%E5%9D%A6%E5%9F%9F%E7%9B%B4%E8%BE%BE%22%5D%0A%20%20XF%20--%3E%20FAST%5B%22%E5%BB%B6%E8%BF%9F%E6%8C%89%E5%8A%A0%E9%80%9F%E5%99%A8%E4%BA%92%E8%BF%9E%E8%AE%A1%22%5D%0A%20%20SW%20--%20%22%E6%97%A0%EF%BC%9A%E6%9C%89%E9%99%90%E7%9B%B4%E8%BF%9E%22%20--%3E%20FWD%5B%22%E9%82%BB%E5%B1%85%E5%8D%A1%E9%80%90%E8%B7%B3%E8%BD%AC%E5%8F%91%22%5D%0A%20%20FWD%20--%3E%20MID%5B%22All-Reduce%20%E8%A2%AB%E6%9C%80%E8%BF%9C%E4%B8%80%E5%AF%B9%E6%8B%96%E4%BD%8F%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[B(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=n('<p>代数上，A100 用更多链路堆出 600 GB/s，H100 再堆到 900 GB/s，Blackwell 把每 GPU 提到 1.8 TB/s。链路数与每条速率的拆分，以该代白皮书为准；产品页通常只给聚合。规划用聚合。域的扩展靠 Switch 端口：节点内几颗 Switch 芯片，机柜内九个托盘，是封装问题，对 CUDA 仍是 device 之间的 P2P。</p><p><span class="marginnote">「14× PCIe Gen5」是 NVIDIA 技术博客对 1.8 TB/s 相对 PCIe Gen5 的对照，用来建立量级，不是某一 kernel 的实测加速比。</span></p><h3 id="故障与降级" tabindex="-1">故障与降级 <a class="header-anchor" href="#故障与降级" aria-label="Permalink to &quot;故障与降级&quot;">​</a></h3><p>单条 NVLink 降级，NCCL 可能改走剩余链路或更差路径，busbw 下降。NVSwitch 或交换托盘故障，域的对称性破坏，表现为集体通信超时或部分 rank 极慢。PCIe 故障不影响已建立的 NVLink 域内流量，但会影响主机启动与网卡。监控要把 NVLink 错误计数、Switch 健康与 NCCL 超时分开。维护超节点时按域下线，见 <a href="/llm/rack-as-accelerator">机柜作为逻辑加速器</a>。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把 H100 NVL 的 600 GB/s 写进 SXM 集群的规划。不要把 NVLink 聚合当成 HBM 带宽。不要期望 MIG 实例享有完整 GPU 的 NVLink 注入。不要在以太网集群上用「逻辑 NVLink」一类营销词去切 64 路 TP。不要填写 Rubin 或其他未在当前产品页给出聚合带宽的下一代数字。</p><p><span class="marginnote">常见误区：把 NVLink 的 1.8 TB/s 与 HBM 的几 TB/s 混为一谈。前者是卡与卡之间的走廊宽度，后者是卡内计算读自己显存的速度——两者不可加总，也互相替代不了。</span></p><p>PCIe 桥接的双卡 NVLink 与 HGX 全互连不是同一拓扑：前者只覆盖一对卡。买了桥不要当 8 卡域。其他厂商的 GPU 互连（Infinity Fabric、华为互连等）名称与带宽以各自文档为准，不能把 1.8 TB/s 抄过去。</p><p><span class="marginnote">出处：NVIDIA A100 数据手册、H100 产品页、GB200 技术博客与 NVL72 产品页、CUDA / NCCL 拓扑行为。单 lane 速率以白皮书已写明者为限，否则只引用聚合规格。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>NVLink 是 GPU–GPU 专用互连；已公布聚合：A100 600 GB/s，H100 SXM 900 GB/s，Blackwell 1.8 TB/s。</li><li>NVSwitch 把链路收成平坦域；NVL72 的 Switch System 把域扩到 72 卡、聚合 130 TB/s。</li><li>C2C 900 GB/s 是 Grace–GPU；PCIe Gen5 128 GB/s 是主机 I/O。三者不可加总成一条「GPU 带宽」。</li><li>最密的集合通信必须落在 NVLink 域；跨柜走网卡。P2P 关闭等于放弃 Switch。</li><li>规划只用产品页聚合规格，不编造单通道速率；故障按域隔离。</li><li>出处：NVIDIA 公开规格与 NCCL / CUDA 文档。</li></ul>',11))])}const k=r(o,[["render",A]]);export{d as __pageData,k as default};
